glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
uniform sampler2D textureWave;
#endif
uniform Vert {
  vec2 waveMove;
  float waveSpeed;
  float waveSize;
  float waveUVSizeY;
};
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
    v_uv0 = a_uv0;
    vec2 newUV = a_uv0;
    #if FLIP_DEPTH
      newUV *= waveUVSizeY * v_uv0.y;
    #else
      newUV *= waveUVSizeY * 1.0 - v_uv0.y;
    #endif
    float time = waveSpeed * cc_time.x;
    #if ENABLE_HEIGHT
      pos.y += texture(textureWave, vec2(newUV + (waveMove *  time))).r * waveSize;
    #endif
  #endif
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
uniform sampler2D textureLight;
uniform sampler2D textureBump;
uniform sampler2D textureWave;
#endif
uniform LOD {
  vec4 mainColor;
  vec4 lightColor1;
  vec4 lightColor2;
  vec4 waveColor;
  vec4 lineSurfaceColor;
  vec2 lightMove1;
  vec2 lightMove2;
  vec2 waveMove;
  vec2 alphaDepth;
  float lightOscillation1;
  float lightOscillation2;
  float lightSpeed1;
  float lightSpeed2;
  float waveSpeed;
  float lightStrength1;
  float lightStrength2;
  float waveStrength;
  float uvSize1Y;
  float uvSize2Y;
  float waveUVSizeY;
  float uvSize1X;
  float uvSize2X;
  float waveUVSizeX;
  float lineAlpha;
  float linePos;
  float lineHeight;
  float lineStrength;
  float lineGr1;
  float lineGr2;
  float uvBumpSize;
};
float cubicPulse( float c, float w, float x, float pos1, float pos2 ){
  x = abs(x - c);
  if( x>w ) return 0.0;
  x /= w;
  return 1.0 - x*x*(pos1-pos2*x);
}
void main () {
  #if USE_TEXTURE
    vec4 color = mainColor;
    vec2 bump = texture(textureBump,v_uv0 * uvBumpSize).rg;
    float time1 = lightSpeed1 * cc_time.x;
    float time2 = lightSpeed2 * cc_time.x;
    float time3 = waveSpeed * cc_time.x;
    vec2 newUV1 = v_uv0 * uvSize1X;
    vec2 newUV2 = v_uv0 * uvSize2X;
    vec2 newUV3 = v_uv0 * waveUVSizeX;
    #if FLIP_DEPTH
      newUV1 *= uvSize1Y * (0.5 + v_uv0.y);
      newUV2 *= uvSize2Y * (0.5 + v_uv0.y);
      newUV3 *= waveUVSizeY * (0.5 + v_uv0.y);
    #else
      newUV1 *= uvSize1Y * 1.0 - v_uv0.y;
      newUV2 *= uvSize2Y * 1.0 - v_uv0.y;
      newUV3 *= waveUVSizeY * 1.0 - v_uv0.y;
    #endif
    vec4 lights1 = texture(textureLight, vec2(newUV1 + (lightMove1 * time1) + (bump * lightOscillation1))) * lightColor1 * lightStrength1;
    vec4 lights2 = texture(textureLight, vec2(newUV2 + (lightMove2 * time2) + (bump * lightOscillation2))) * lightColor2 * lightStrength2;
    vec4 waveLights = texture(textureWave, vec2(newUV3 + (waveMove * time3))) * waveColor * waveStrength;
    float cubic  = cubicPulse(linePos,lineHeight,v_uv0.y,lineGr1, lineGr2);
    vec3 lineColor = vec3(cubic);
    lineColor *= lineSurfaceColor.rgb;
    color.rgb += lights1.rgb + lights2.rgb + waveLights.rgb + (lineStrength * lineColor);
    color.a = pow(v_uv0.y,alphaDepth.y) + alphaDepth.x;
    #if FLIP_DEPTH
      color.a = -v_uv0.y + lightMove1.y + alphaDepth.x;
    #endif
    color.a *= alphaDepth.y;
  #endif
  gl_FragColor = color ;
}

glsl1.vert:
precision highp float;
uniform mat4 cc_matViewProj;
uniform vec4 cc_time;
uniform mat4 cc_matWorld;
attribute vec3 a_position;
#if USE_TEXTURE
attribute vec2 a_uv0;
varying vec2 v_uv0;
uniform sampler2D textureWave;
#endif
uniform vec2 waveMove;
uniform float waveSpeed;
uniform float waveSize;
uniform float waveUVSizeY;
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
    v_uv0 = a_uv0;
    vec2 newUV = a_uv0;
    #if FLIP_DEPTH
      newUV *= waveUVSizeY * v_uv0.y;
    #else
      newUV *= waveUVSizeY * 1.0 - v_uv0.y;
    #endif
    float time = waveSpeed * cc_time.x;
    #if ENABLE_HEIGHT
      pos.y += texture2D(textureWave, vec2(newUV + (waveMove *  time))).r * waveSize;
    #endif
  #endif
  gl_Position = pos;
}

